diff --git a/libavformat/hlsenc.c b/libavformat/hlsenc.c
index 571d6b2752..5bcce15cbe 100644
--- a/libavformat/hlsenc.c
+++ b/libavformat/hlsenc.c
@@ -1195,20 +1195,36 @@ static int hls_append_segment(struct AVFormatContext *s, HLSContext *hls,
         vs->nb_entries++;

     if (hls->max_seg_size > 0) {
         return 0;
     }
     vs->sequence++;

     return 0;
 }

+static int extract_segment_number(const char *filename) {
+    const char *dot = strrchr(filename, '.');
+    const char *num_start = dot - 1;
+
+    while (num_start > filename && *num_start >= '0' && *num_start <= '9') {
+        num_start--;
+    }
+
+    num_start++;
+
+    if (num_start == dot)
+        return -1;
+
+    return atoi(num_start);
+}
+
 static int parse_playlist(AVFormatContext *s, const char *url, VariantStream *vs)
 {
     HLSContext *hls = s->priv_data;
     AVIOContext *in;
     int ret = 0, is_segment = 0;
     int64_t new_start_pos;
     char line[MAX_URL_SIZE];
     const char *ptr;
     const char *end;
     double discont_program_date_time = 0;
@@ -1288,20 +1304,34 @@ static int parse_playlist(AVFormatContext *s, const char *url, VariantStream *vs
         } else if (av_strstart(line, "#", NULL)) {
             continue;
         } else if (line[0]) {
             if (is_segment) {
                 char *new_file = av_strdup(line);
                 if (!new_file) {
                     ret = AVERROR(ENOMEM);
                     goto fail;
                 }
                 ff_format_set_url(vs->avf, new_file);
+
+                if (vs->has_subtitle) {
+                    int vtt_index = extract_segment_number(line);
+                    const char *vtt_basename = av_basename(vs->vtt_basename);
+                    char *vtt_file = NULL;
+                    int ret = replace_int_data_in_filename(&vtt_file, vtt_basename, 'd', vtt_index);
+                    if (ret < 0 || !vtt_file) {
+                        ret = AVERROR(ENOMEM);
+                        goto fail;
+                    }
+
+                    ff_format_set_url(vs->vtt_avf, vtt_file);
+                }
+
                 is_segment = 0;
                 new_start_pos = avio_tell(vs->avf->pb);
                 vs->size = new_start_pos - vs->start_pos;
                 ret = hls_append_segment(s, hls, vs, vs->duration, vs->start_pos, vs->size);
                 if (discont_program_date_time) {
                     vs->last_segment->discont_program_date_time = discont_program_date_time;
                     discont_program_date_time += vs->duration;
                 }
                 if (ret < 0)
                     goto fail;

